#!/usr/bin/env node

/**
 * Builds skill-pack coverage documentation from catalog/catalog.json, the single source of truth for
 * how the 400-item capability catalog maps onto the packs.
 *
 *   node bin/build-catalog.js           validate, then rewrite CATALOG_CROSSWALK.md and SKILL.md blocks
 *   node bin/build-catalog.js --check   validate, and exit 1 if any generated file is out of date
 *
 * Validation is what keeps "coverage" honest: a tier that claims code must name engines the library
 * actually exports (or files that exist), and reference tiers are only allowed in their own section.
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const CATALOG = path.join(root, 'catalog', 'catalog.json');
const CROSSWALK = path.join(root, 'CATALOG_CROSSWALK.md');
const README = path.join(root, 'README.md');

export const PACKS = ['wealth-planning', 'wealth-portfolio', 'wealth-execution', 'wealth-onboarding', 'wealth-compliance', 'wealth-crm', 'wealth-research', 'wealth-uhnw', 'wealth-fund-ops'];
const SECTION_ORDER = ['T', 'S', 'G', 'R'];
const CODE_TIERS = ['engine', 'partial-engine', 'payload-builder'];
const REFERENCE_SECTION = { 'standard-reference': 'S', 'integration-reference': 'G', 'research-reference': 'R' };
const BLOCK_START = '<!-- catalog:start -->';
const BLOCK_END = '<!-- catalog:end -->';

export function loadCatalog() {
  return JSON.parse(fs.readFileSync(CATALOG, 'utf8'));
}

export async function validateCatalog(catalog) {
  const problems = [];
  const exported = new Set(Object.keys(await import(path.join(root, 'src', 'index.js'))));
  const tiers = Object.keys(catalog.tiers);
  const seen = new Set();

  for (const item of catalog.items) {
    const where = item.id ?? '(no id)';
    if (!/^[TSGR]\d{3}$/.test(item.id ?? '')) problems.push(`${where}: invalid id`);
    if (seen.has(item.id)) problems.push(`${where}: duplicate id`);
    seen.add(item.id);
    if (item.section !== item.id?.[0]) problems.push(`${where}: section does not match id`);
    for (const field of ['name', 'url', 'capability', 'note']) if (!item[field]) problems.push(`${where}: missing ${field}`);
    if (!PACKS.includes(item.pack)) problems.push(`${where}: unknown pack ${item.pack}`);
    if (!tiers.includes(item.tier)) problems.push(`${where}: unknown tier ${item.tier}`);

    const engines = item.engines ?? [];
    const implementation = item.implementation ?? [];
    if (CODE_TIERS.includes(item.tier)) {
      if (engines.length === 0 && implementation.length === 0) problems.push(`${where}: ${item.tier} must name engines or an implementation`);
    } else if (engines.length > 0 || implementation.length > 0) {
      problems.push(`${where}: ${item.tier} cannot claim engines; use relatedEngines`);
    }
    for (const name of [...engines, ...(item.relatedEngines ?? [])]) {
      if (!exported.has(name)) problems.push(`${where}: engine ${name} is not exported by src/index.js`);
    }
    for (const file of implementation) {
      if (!fs.existsSync(path.join(root, file))) problems.push(`${where}: implementation ${file} does not exist`);
    }
    if (REFERENCE_SECTION[item.tier] && REFERENCE_SECTION[item.tier] !== item.section) {
      problems.push(`${where}: ${item.tier} is only for section ${REFERENCE_SECTION[item.tier]}`);
    }
  }

  for (const section of SECTION_ORDER) {
    for (let n = 1; n <= 100; n++) {
      const id = `${section}${String(n).padStart(3, '0')}`;
      if (!seen.has(id)) problems.push(`${id}: missing from catalog`);
    }
  }
  if (catalog.items.length !== 400) problems.push(`expected 400 items, found ${catalog.items.length}`);
  for (const pack of PACKS) {
    if (!fs.existsSync(path.join(root, 'skills', pack, 'SKILL.md'))) problems.push(`pack ${pack} has no SKILL.md`);
  }
  return problems;
}

const esc = (text) => String(text).replace(/\|/g, '\\|');
const sortItems = (items) => [...items].sort((a, b) => SECTION_ORDER.indexOf(a.section) - SECTION_ORDER.indexOf(b.section) || a.id.localeCompare(b.id));
const count = (items, predicate) => items.filter(predicate).length;

function renderCrosswalk(catalog) {
  const { items, tiers, sections } = catalog;
  const tierNames = Object.keys(tiers);
  const codeBacked = count(items, i => CODE_TIERS.includes(i.tier));

  let md = `# US Wealth Management Capability Catalog Crosswalk

<!-- Generated by \`npm run catalog\` from catalog/catalog.json. Edit the JSON, not this file. -->

All **${items.length}** catalog resources are assigned to a \`wealth-skills\` pack with a coverage tier. **${codeBacked}** are backed by engine code; the rest are workflow guidance or cited references. Assignment is not implementation: the tier says exactly how much of each resource this library does, and nothing here replaces a named commercial product.

## Tiers

| Tier | Meaning | Items |
|---|---|---|
${tierNames.map(t => `| \`${t}\` | ${tiers[t]} | ${count(items, i => i.tier === t)} |`).join('\n')}

## By Section

| Section | ${tierNames.map(t => `\`${t}\``).join(' | ')} | Total |
|---|${tierNames.map(() => '---:').join('|')}|---:|
${SECTION_ORDER.map(s => `| **${s}** ${sections[s]} | ${tierNames.map(t => count(items, i => i.section === s && i.tier === t) || '-').join(' | ')} | ${count(items, i => i.section === s)} |`).join('\n')}

## By Pack

| Pack | Code-backed | Guidance | References | Total |
|---|---:|---:|---:|---:|
${PACKS.map(p => {
  const own = items.filter(i => i.pack === p);
  return `| [\`${p}\`](skills/${p}/SKILL.md) | ${count(own, i => CODE_TIERS.includes(i.tier))} | ${count(own, i => i.tier === 'guidance')} | ${count(own, i => REFERENCE_SECTION[i.tier])} | ${own.length} |`;
}).join('\n')}

Code-backed means \`engine\`, \`partial-engine\` or \`payload-builder\`.
`;

  for (const section of SECTION_ORDER) {
    md += `
## ${section} - ${sections[section]}

| ID | Resource | Capability | Pack | Tier | Engines | Note |
|---|---|---|---|---|---|---|
`;
    for (const item of sortItems(items.filter(i => i.section === section))) {
      const engines = [
        ...(item.engines ?? []).map(e => `\`${e}\``),
        ...(item.implementation ?? []).map(f => `\`${f}\``),
        ...(item.relatedEngines ?? []).map(e => `related: \`${e}\``)
      ].join('<br>') || '-';
      md += `| ${item.id} | [${esc(item.name)}](${item.url}) | ${esc(item.capability)} | \`${item.pack.replace('wealth-', '')}\` | ${item.tier} | ${engines} | ${esc(item.note)} |\n`;
    }
  }
  return md;
}

function renderPackBlock(catalog, pack) {
  const own = sortItems(catalog.items.filter(i => i.pack === pack));
  const codeBacked = count(own, i => CODE_TIERS.includes(i.tier));
  const rows = Object.keys(catalog.tiers)
    .map(t => [t, own.filter(i => i.tier === t)])
    .filter(([, list]) => list.length > 0)
    .map(([t, list]) => `| \`${t}\` | ${list.length} | ${list.map(i => i.id).join(', ')} |`)
    .join('\n');

  return `${BLOCK_START}
## Catalog Coverage

Generated from \`catalog/catalog.json\` by \`npm run catalog\`. See [CATALOG_CROSSWALK.md](../../CATALOG_CROSSWALK.md) for each item's name and what is and is not covered.

This pack is assigned **${own.length}** catalog items; **${codeBacked}** are backed by engine code.

| Tier | Items | IDs |
|---|---:|---|
${rows}

---

${BLOCK_END}`;
}

function renderSkill(current, catalog, pack) {
  const ids = sortItems(catalog.items.filter(i => i.pack === pack)).map(i => `"${i.id}"`).join(', ');
  let next = current.replace(/^catalog_ids:.*$/m, `catalog_ids: [${ids}]`);
  const block = renderPackBlock(catalog, pack);

  if (next.includes(BLOCK_START)) {
    const start = next.indexOf(BLOCK_START);
    const end = next.indexOf(BLOCK_END) + BLOCK_END.length;
    next = next.slice(0, start) + block + next.slice(end);
  } else {
    const anchor = next.indexOf('## Output Standard');
    if (anchor === -1) throw new Error(`skills/${pack}/SKILL.md has no "## Output Standard" heading to place the coverage block before`);
    next = next.slice(0, anchor) + block + '\n\n' + next.slice(anchor);
  }
  return next;
}

function renderReadmeBlock(catalog) {
  const { items } = catalog;
  const n = (tier) => count(items, i => i.tier === tier);
  const code = count(items, i => CODE_TIERS.includes(i.tier));
  return `${BLOCK_START}
Every one of the **${items.length}** resources in the US Wealth Management Capability Catalog is assigned to a pack with a coverage tier, recorded in [catalog/catalog.json](catalog/catalog.json) and published in [CATALOG_CROSSWALK.md](CATALOG_CROSSWALK.md). Assignment is not implementation; the tier says how much of each resource the library actually does.

| Coverage | Items | Tiers |
|---|---:|---|
| Backed by engine code | ${code} | ${n('engine')} engine, ${n('partial-engine')} partial engine, ${n('payload-builder')} payload builder |
| Workflow guidance only | ${n('guidance')} | guidance |
| Cited references | ${n('standard-reference') + n('integration-reference') + n('research-reference')} | ${n('standard-reference')} standards and rules, ${n('integration-reference')} open-source integrations, ${n('research-reference')} research papers |

\`npm run catalog\` validates every claim: a tier that claims code must name engines the library exports.
${BLOCK_END}`;
}

function renderReadme(current, catalog) {
  if (!current.includes(BLOCK_START)) throw new Error('README.md has no catalog block markers.');
  const start = current.indexOf(BLOCK_START);
  const end = current.indexOf(BLOCK_END) + BLOCK_END.length;
  return current.slice(0, start) + renderReadmeBlock(catalog) + current.slice(end);
}

export function renderAll(catalog) {
  const outputs = new Map([[CROSSWALK, renderCrosswalk(catalog)], [README, renderReadme(fs.readFileSync(README, 'utf8'), catalog)]]);
  for (const pack of PACKS) {
    const file = path.join(root, 'skills', pack, 'SKILL.md');
    outputs.set(file, renderSkill(fs.readFileSync(file, 'utf8'), catalog, pack));
  }
  return outputs;
}

async function main() {
  const check = process.argv.includes('--check');
  const catalog = loadCatalog();
  const problems = await validateCatalog(catalog);
  if (problems.length > 0) {
    console.error(`catalog.json has ${problems.length} problem(s):\n  ${problems.join('\n  ')}`);
    process.exitCode = 1;
    return;
  }

  const outputs = renderAll(catalog);
  const stale = [...outputs].filter(([file, content]) => !fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== content).map(([file]) => path.relative(root, file));

  if (check) {
    if (stale.length > 0) {
      console.error(`Out of date (run npm run catalog): ${stale.join(', ')}`);
      process.exitCode = 1;
    } else {
      console.log('Catalog documentation is up to date.');
    }
    return;
  }

  for (const [file, content] of outputs) fs.writeFileSync(file, content);
  const codeBacked = count(catalog.items, i => CODE_TIERS.includes(i.tier));
  console.log(`Validated ${catalog.items.length} items (${codeBacked} code-backed). Updated: ${stale.length ? stale.join(', ') : 'nothing changed'}.`);
}

let isMain = false;
try {
  isMain = Boolean(process.argv[1]) && fs.realpathSync(process.argv[1]) === fs.realpathSync(fileURLToPath(import.meta.url));
} catch {
  isMain = false;
}
if (isMain) await main();
